// --- Shared-framework wrappers ----------------------------------------------
// Self-paced: no cohort start, so every row's date is null by design and the UI
// shows a lesson number rather than a fabricated calendar date (DR-0076).

export function buildBuyingTermsSchedule(startISO = null) {
  return buildScheduleFor(BUYING_TERMS_MODULES, startISO, BUYING_TERMS_META.cadenceDays);
}

export function buyingTermsProgressSummary(progress = {}) {
  return progressSummaryFor(BUYING_TERMS_MODULES, progress);
}

export function exportBuyingTermsCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: BUYING_TERMS_META,
    modules: buildBuyingTermsSchedule(startISO),
    sessionFlow: BUYING_TERMS_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function buyingTermsRefs() {
  const seen = new Set();
  for (const m of BUYING_TERMS_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((BUYING_TERMS_META.wordFirst && BUYING_TERMS_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

